def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v not in (0,))
    marker = max((v for v in counts if counts[v] < 20), key=lambda v: sum(row.count(v) for row in grid), default=None)
    # The marker is the rare non-background color embedded in a noisy field.
    vals = Counter(v for row in grid for v in row)
