    if rare:
        marker = rare[0]
    if marker is None:
        return [row[:] for row in grid]
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    shape={(r-r0,c-c0) for r,c in pts}
    mh,mw=r1-r0+1,c1-c0+1
    # Find exact translated repetitions of the marked stencil on zero cells,
    # retaining all existing pixels. A match is evaluated against zero-valued
    # target cells at the marked offsets.
    out=[row[:] for row in grid]
    for r in range(h-mh+1):
        for c in range(w-mw+1):
            if all(grid[r+dr][c+dc] == 0 for dr,dc in shape):
